// Why data structure choice matters: searching in array vs set
#include <iostream>
#include <vector>
#include <unordered_set>
#include <chrono>
using namespace std;

int main() {
    const int N = 100000;
    vector<int> arr;
    unordered_set<int> s;

    // Fill with data
    for (int i = 0; i < N; i++) {
        arr.push_back(i);
        s.insert(i);
    }

    int target = N - 1;

    // Linear search in array: O(n)
    auto t1 = chrono::high_resolution_clock::now();
    bool found_arr = false;
    for (int x : arr) {
        if (x == target) { found_arr = true; break; }
    }
    auto t2 = chrono::high_resolution_clock::now();

    // Hash set lookup: O(1) average
    auto t3 = chrono::high_resolution_clock::now();
    bool found_set = (s.find(target) != s.end());
    auto t4 = chrono::high_resolution_clock::now();

    auto dt_arr = chrono::duration_cast<chrono::microseconds>(t2 - t1).count();
    auto dt_set = chrono::duration_cast<chrono::microseconds>(t4 - t3).count();

    cout << "Array linear search: " << dt_arr << " us\n";
    cout << "Hash set lookup:   " << dt_set << " us\n";
    cout << "Speedup: " << (double)dt_arr / dt_set << "x\n";

    return 0;
}

