    cout << "=== Data Structure Selection Guide ===\n\n";

    cout << "Array/Vector:\n";
    cout << "  Use when: fixed or known max size, fast index access needed\n";
    cout << "  Trade-off: slow insertion/deletion in middle (O(n))\n\n";

    cout << "Linked List:\n";
    cout << "  Use when: frequent insertions/deletions at ends or middle\n";
    cout << "  Trade-off: no random access, extra memory for pointers\n\n";

    cout << "Stack:\n";
    cout << "  Use when: LIFO order needed (undo, backtracking, parsing)\n";
    cout << "  Trade-off: limited access (only top element)\n\n";

    cout << "Queue:\n";
    cout << "  Use when: FIFO order needed (BFS, scheduling, buffers)\n";
    cout << "  Trade-off: limited access (only front element)\n\n";

    cout << "Binary Search Tree:\n";
    cout << "  Use when: ordered data with fast search/insert/delete\n";
    cout << "  Trade-off: needs balancing for guaranteed O(log n)\n\n";

    cout << "Hash Table:\n";
    cout << "  Use when: fastest possible lookup by key\n";
    cout << "  Trade-off: no ordering, needs good hash function\n";

    return 0;
}

// Arrays and Vectors in C++
#include <iostream>
#include <vector>
using namespace std;

int main() {
    // Static array (stack allocated, fixed size)
    int staticArr[5] = {10, 20, 30, 40, 50};
    cout << "Static array: ";
    for (int i = 0; i < 5; i++)
        cout << staticArr[i] << " ";
    cout << "\n";

    // Dynamic array using vector
    vector<int> vec;
    cout << "\nPushing elements to vector...\n";
    for (int i = 1; i <= 5; i++) {
        vec.push_back(i * 10);
        cout << "After push_back(" << i*10 << "): size=" << vec.size()
             << ", capacity=" << vec.capacity() << "\n";
    }

    // Random access
    cout << "\nvec[2] = " << vec[2] << "\n";
    cout << "vec.at(2) = " << vec.at(2) << " (bounds-checked)\n";

    // Insert in middle (shifts elements right)
    vec.insert(vec.begin() + 2, 25);
    cout << "\nAfter insert at index 2: ";
    for (int x : vec) cout << x << " ";
    cout << "\n";

    // Delete from middle (shifts elements left)
    vec.erase(vec.begin() + 3);
    cout << "After erase at index 3: ";
    for (int x : vec) cout << x << " ";
    cout << "\n";

    // Reserve capacity to avoid reallocations
    vector<int> vec2;
    vec2.reserve(100);
    cout << "\nReserved capacity: " << vec2.capacity() << "\n";

    return 0;
}

// Binary search on sorted array/vector
#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int binarySearch(const vector<int>& arr, int target) {
    int left = 0, right = arr.size() - 1;
    while (left <= right) {
        int mid = left + (right - left) / 2;
        if (arr[mid] == target) return mid;
        if (arr[mid] < target) left = mid + 1;
        else right = mid - 1;
    }
    return -1;
}

int main() {
    vector<int> arr = {2, 5, 8, 12, 16, 23, 38, 56, 72, 91};

    cout << "Array: ";
    for (int x : arr) cout << x << " ";
    cout << "\n\n";

    int targets[] = {23, 100, 2};
    for (int t : targets) {
        int idx = binarySearch(arr, t);
        if (idx != -1)
            cout << t << " found at index " << idx << "\n";
        else
            cout << t << " not found\n";
    }

    // Using STL lower_bound (also binary search)
    auto it = lower_bound(arr.begin(), arr.end(), 16);
    cout << "\nlower_bound(16) points to: " << *it
         << " at index " << (it - arr.begin()) << "\n";

    return 0;
}

// Singly Linked List from scratch in C++
#include <iostream>
using namespace std;

struct Node {
    int data;
    Node* next;

    Node(int val) : data(val), next(nullptr) {}
};

class LinkedList {
    Node* head;

public:
    LinkedList() : head(nullptr) {}

    // Add to front: O(1)
    void prepend(int val) {
        Node* newNode = new Node(val);
        newNode->next = head;
        head = newNode;
    }

    // Add to end: O(n)
    void append(int val) {
        Node* newNode = new Node(val);
        if (!head) {
            head = newNode;
            return;
        }
        Node* curr = head;
        while (curr->next) curr = curr->next;
        curr->next = newNode;
    }

    // Search: O(n)
    bool search(int val) {
        Node* curr = head;
        while (curr) {
            if (curr->data == val) return true;
            curr = curr->next;
        }
        return false;
    }

    // Delete first occurrence: O(n)
    void remove(int val) {
        if (!head) return;
        if (head->data == val) {
            Node* temp = head;
            head = head->next;
            delete temp;
            return;
        }
        Node* curr = head;
        while (curr->next && curr->next->data != val)
            curr = curr->next;
        if (curr->next) {
            Node* temp = curr->next;
            curr->next = curr->next->next;
            delete temp;
        }
    }

    // Display: O(n)
    void display() {
        Node* curr = head;
        while (curr) {
            cout << curr->data << " -> ";
            curr = curr->next;
        }
        cout << "nullptr\n";
    }

    // Destructor: free all nodes
    ~LinkedList() {
        while (head) {
            Node* temp = head;
            head = head->next;
            delete temp;
        }
    }
};

int main() {
    LinkedList list;

    list.append(10);
    list.append(20);
    list.append(30);
    cout << "After appends: ";
    list.display();

    list.prepend(5);
    cout << "After prepend(5): ";
    list.display();

    cout << "\nSearch 20: " << (list.search(20) ? "Found" : "Not found") << "\n";
    cout << "Search 99: " << (list.search(99) ? "Found" : "Not found") << "\n";

    list.remove(20);
    cout << "\nAfter remove(20): ";
    list.display();

    return 0;
}

// Linked List vs Vector: memory and performance comparison
#include <iostream>
#include <vector>
#include <chrono>
using namespace std;

struct ListNode {
    int data;
    ListNode* next;
    ListNode(int v) : data(v), next(nullptr) {}
};

int main() {
    const int N = 100000;

    // Linked list prepend (O(1) each)
    auto t1 = chrono::high_resolution_clock::now();
    ListNode* head = nullptr;
    for (int i = 0; i < N; i++) {
        ListNode* n = new ListNode(i);
        n->next = head;
        head = n;
    }
    auto t2 = chrono::high_resolution_clock::now();

    // Vector insert at beginning (O(n) each = O(n^2) total)
    auto t3 = chrono::high_resolution_clock::now();
    vector<int> vec;
    for (int i = 0; i < N; i++) {
        vec.insert(vec.begin(), i);
    }
    auto t4 = chrono::high_resolution_clock::now();

    auto dt_list = chrono::duration_cast<chrono::milliseconds>(t2 - t1).count();
    auto dt_vec = chrono::duration_cast<chrono::milliseconds>(t4 - t3).count();

    cout << "Linked list prepend " << N << " items: " << dt_list << " ms\n";
    cout << "Vector insert at front " << N << " items: " << dt_vec << " ms\n";

    // Cleanup list
    while (head) {
        ListNode* temp = head;
        head = head->next;
        delete temp;
    }

    return 0;
}

// Stack implementation using array (from scratch)
#include <iostream>
using namespace std;

class Stack {
    int* arr;
    int capacity;
    int topIndex;

public:
    Stack(int cap) {
        capacity = cap;
        arr = new int[capacity];
        topIndex = -1;
    }

    void push(int val) {
        if (topIndex >= capacity - 1) {
            cout << "Stack Overflow!\n";
            return;
        }
        arr[++topIndex] = val;
    }

    int pop() {
        if (isEmpty()) {
            cout << "Stack Underflow!\n";
            return -1;
        }
        return arr[topIndex--];
    }

    int top() {
        if (isEmpty()) {
            cout << "Stack is empty!\n";
            return -1;
        }
        return arr[topIndex];
    }

    bool isEmpty() {
        return topIndex == -1;
    }

    int size() {
        return topIndex + 1;
    }

    void display() {
        cout << "Stack (top to bottom): ";
        for (int i = topIndex; i >= 0; i--)
            cout << arr[i] << " ";
        cout << "\n";
    }

    ~Stack() {
        delete[] arr;
    }
};

int main() {
    Stack s(5);

    s.push(10);
    s.push(20);
    s.push(30);
    s.display();

    cout << "Top element: " << s.top() << "\n";
    cout << "Popped: " << s.pop() << "\n";
    s.display();

    s.push(40);
    s.push(50);
    s.push(60);
    s.display();

    s.push(70);  // Should show overflow

    return 0;
}

// Balanced parentheses using stack
#include <iostream>
#include <stack>
#include <string>
using namespace std;

bool isBalanced(const string& expr) {
    stack<char> s;

    for (char ch : expr) {
        if (ch == '(' || ch == '[' || ch == '{') {
            s.push(ch);
        }
        else if (ch == ')' || ch == ']' || ch == '}') {
            if (s.empty()) return false;

            char top = s.top();
            if ((ch == ')' && top != '(') ||
                (ch == ']' && top != '[') ||
                (ch == '}' && top != '{')) {
                return false;
            }
            s.pop();
        }
    }
    return s.empty();
}

int main() {
    string tests[] = {
        "(a + b) * (c - d)",
        "{[()]}",
        "((())",
        "[{]}",
        ""
    };

    for (const string& expr : tests) {
        cout << "\"" << expr << "\" -> "
             << (isBalanced(expr) ? "Balanced" : "NOT Balanced") << "\n";
    }

    return 0;
}

// Circular Queue implementation from scratch
#include <iostream>
using namespace std;

class CircularQueue {
    int* arr;
    int capacity;
    int front;
    int rear;
    int count;

public:
    CircularQueue(int cap) {
        capacity = cap;
        arr = new int[capacity];
        front = 0;
        rear = -1;
        count = 0;
    }

    void enqueue(int val) {
        if (isFull()) {
            cout << "Queue is full!\n";
            return;
        }
        rear = (rear + 1) % capacity;
        arr[rear] = val;
        count++;
    }

    int dequeue() {
        if (isEmpty()) {
            cout << "Queue is empty!\n";
            return -1;
        }
        int val = arr[front];
        front = (front + 1) % capacity;
        count--;
        return val;
    }

    int peek() {
        if (isEmpty()) {
            cout << "Queue is empty!\n";
            return -1;
        }
        return arr[front];
    }

    bool isEmpty() { return count == 0; }
    bool isFull() { return count == capacity; }
    int size() { return count; }

    void display() {
        cout << "Queue (front to rear): ";
        for (int i = 0; i < count; i++) {
            cout << arr[(front + i) % capacity] << " ";
        }
        cout << "\n";
    }

    ~CircularQueue() { delete[] arr; }
};

int main() {
    CircularQueue q(5);

    q.enqueue(10);
    q.enqueue(20);
    q.enqueue(30);
    q.display();

    cout << "Dequeued: " << q.dequeue() << "\n";
    q.display();

    q.enqueue(40);
    q.enqueue(50);
    q.enqueue(60);
    q.display();

    // Demonstrate wrap-around
    q.enqueue(70);  // Full
    cout << "Dequeued: " << q.dequeue() << "\n";
    q.enqueue(70);  // Now fits in wrapped position
    q.display();

    return 0;
}

// BFS using queue (Level Order Traversal of a tree)
#include <iostream>
#include <queue>
using namespace std;

struct TreeNode {
    int val;
    TreeNode* left;
    TreeNode* right;
    TreeNode(int v) : val(v), left(nullptr), right(nullptr) {}
};

void levelOrder(TreeNode* root) {
    if (!root) return;

    queue<TreeNode*> q;
    q.push(root);

    cout << "Level Order Traversal: ";
    while (!q.empty()) {
        TreeNode* curr = q.front();
        q.pop();
        cout << curr->val << " ";

        if (curr->left) q.push(curr->left);
        if (curr->right) q.push(curr->right);
    }
    cout << "\n";
}

