// Tree properties and mirror operation
#include <iostream>
using namespace std;

struct TreeNode {
    int data;
    TreeNode* left;
    TreeNode* right;
    TreeNode(int v) : data(v), left(nullptr), right(nullptr) {}
};

// Mirror: swap left and right subtrees recursively
void mirror(TreeNode* root) {
    if (!root) return;
    swap(root->left, root->right);
    mirror(root->left);
    mirror(root->right);
}

void inorder(TreeNode* root) {
    if (!root) return;
    inorder(root->left);
    cout << root->data << " ";
    inorder(root->right);
}

int main() {
    TreeNode* root = new TreeNode(1);
    root->left = new TreeNode(2);
    root->right = new TreeNode(3);
    root->left->left = new TreeNode(4);
    root->left->right = new TreeNode(5);

    cout << "Original inorder: ";
    inorder(root);
    cout << "\n";

    mirror(root);

    cout << "Mirrored inorder: ";
    inorder(root);
    cout << "\n";

    return 0;
}

// Binary Search Tree: search, insert, inorder traversal
#include <iostream>
using namespace std;

struct TreeNode {
    int data;
    TreeNode* left;
    TreeNode* right;
    TreeNode(int v) : data(v), left(nullptr), right(nullptr) {}
};

class BST {
    TreeNode* root;

    TreeNode* insertHelper(TreeNode* node, int val) {
        if (!node) return new TreeNode(val);
        if (val < node->data)
            node->left = insertHelper(node->left, val);
        else if (val > node->data)
            node->right = insertHelper(node->right, val);
        return node;
    }

    bool searchHelper(TreeNode* node, int val) {
        if (!node) return false;
        if (node->data == val) return true;
        if (val < node->data)
            return searchHelper(node->left, val);
        return searchHelper(node->right, val);
    }

    void inorderHelper(TreeNode* node) {
        if (!node) return;
        inorderHelper(node->left);
        cout << node->data << " ";
        inorderHelper(node->right);
    }

    TreeNode* findMin(TreeNode* node) {
        while (node && node->left)
            node = node->left;
        return node;
    }

    TreeNode* deleteHelper(TreeNode* node, int val) {
        if (!node) return nullptr;
        if (val < node->data)
            node->left = deleteHelper(node->left, val);
        else if (val > node->data)
            node->right = deleteHelper(node->right, val);
        else {
            // Node found
            if (!node->left) {
                TreeNode* temp = node->right;
                delete node;
                return temp;
            }
            if (!node->right) {
                TreeNode* temp = node->left;
                delete node;
                return temp;
            }
            // Two children: replace with inorder successor
            TreeNode* succ = findMin(node->right);
            node->data = succ->data;
            node->right = deleteHelper(node->right, succ->data);
        }
        return node;
    }

public:
    BST() : root(nullptr) {}

    void insert(int val) { root = insertHelper(root, val); }
    bool search(int val) { return searchHelper(root, val); }
    void remove(int val) { root = deleteHelper(root, val); }

    void inorder() {
        inorderHelper(root);
        cout << "\n";
    }
};

int main() {
    BST tree;
    int values[] = {50, 30, 70, 20, 40, 60, 80};
    for (int v : values) tree.insert(v);

    cout << "Inorder (sorted): ";
    tree.inorder();

    cout << "\nSearch 40: " << (tree.search(40) ? "Found" : "Not found") << "\n";
    cout << "Search 100: " << (tree.search(100) ? "Found" : "Not found") << "\n";

    cout << "\nAfter deleting 30 (has two children):\n";
    tree.remove(30);
    tree.inorder();

    cout << "\nAfter deleting 20 (leaf):\n";
    tree.remove(20);
    tree.inorder();

    return 0;
}

// BST vs sorted array: search comparison
#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

struct TreeNode {
    int data; TreeNode* left; TreeNode* right;
    TreeNode(int v) : data(v), left(nullptr), right(nullptr) {}
};

TreeNode* insert(TreeNode* root, int val) {
    if (!root) return new TreeNode(val);
    if (val < root->data) root->left = insert(root->left, val);
    else root->right = insert(root->right, val);
    return root;
}

bool bstSearch(TreeNode* root, int val, int& comparisons) {
    comparisons++;
    if (!root) return false;
    if (root->data == val) return true;
    if (val < root->data) return bstSearch(root->left, val, comparisons);
    return bstSearch(root->right, val, comparisons);
}

int linearSearch(const vector<int>& arr, int val, int& comparisons) {
    for (int i = 0; i < (int)arr.size(); i++) {
        comparisons++;
        if (arr[i] == val) return i;
    }
    return -1;
}

int main() {
    // Build BST and sorted array with same data
    TreeNode* root = nullptr;
    vector<int> arr;
    for (int i = 1; i <= 1000; i += 2) {
        root = insert(root, i);
        arr.push_back(i);
    }

    int target = 999;
    int bstComp = 0, linComp = 0;

    bstSearch(root, target, bstComp);
    linearSearch(arr, target, linComp);

    cout << "BST search comparisons:    " << bstComp << "\n";
    cout << "Linear search comparisons: " << linComp << "\n";
    cout << "BST is roughly O(log n), linear is O(n)\n";

    return 0;
}

// Hash Table with separate chaining (from scratch)
#include <iostream>
#include <string>
using namespace std;

#define TABLE_SIZE 16

struct HashNode {
    string key;
    int value;
    HashNode* next;
    HashNode(string k, int v) : key(k), value(v), next(nullptr) {}
};

class HashTable {
    HashNode* buckets[TABLE_SIZE];

    unsigned long hashFunc(const string& str) {
        unsigned long hash = 5381;
        for (char c : str)
            hash = ((hash << 5) + hash) + c;
        return hash % TABLE_SIZE;
    }

public:
    HashTable() {
        for (int i = 0; i < TABLE_SIZE; i++)
            buckets[i] = nullptr;
    }

    void insert(const string& key, int value) {
        int idx = hashFunc(key);
        HashNode* curr = buckets[idx];
        while (curr) {
            if (curr->key == key) {
                curr->value = value;  // Update existing
                return;
            }
            curr = curr->next;
        }
        HashNode* n = new HashNode(key, value);
        n->next = buckets[idx];
        buckets[idx] = n;
    }

    int* get(const string& key) {
        int idx = hashFunc(key);
        HashNode* curr = buckets[idx];
        while (curr) {
            if (curr->key == key)
                return &curr->value;
            curr = curr->next;
        }
        return nullptr;
    }

    void remove(const string& key) {
        int idx = hashFunc(key);
        HashNode* curr = buckets[idx];
        HashNode* prev = nullptr;
        while (curr) {
            if (curr->key == key) {
                if (prev) prev->next = curr->next;
                else buckets[idx] = curr->next;
                delete curr;
                return;
            }
            prev = curr;
            curr = curr->next;
        }
    }

    void display() {
        for (int i = 0; i < TABLE_SIZE; i++) {
            if (buckets[i]) {
                cout << "Bucket " << i << ": ";
                HashNode* curr = buckets[i];
                while (curr) {
                    cout << "[" << curr->key << ":" << curr->value << "] -> ";
                    curr = curr->next;
                }
                cout << "nullptr\n";
            }
        }
    }

    ~HashTable() {
        for (int i = 0; i < TABLE_SIZE; i++) {
            while (buckets[i]) {
                HashNode* temp = buckets[i];
                buckets[i] = buckets[i]->next;
                delete temp;
            }
        }
    }
};

int main() {
    HashTable ht;
    ht.insert("apple", 100);
    ht.insert("banana", 200);
    ht.insert("cherry", 300);
    ht.insert("date", 400);

    cout << "Hash table contents:\n";
    ht.display();

    int* val = ht.get("banana");
    if (val)
        cout << "\nbanana -> " << *val << "\n";

    ht.remove("banana");
    cout << "\nAfter removing 'banana':\n";
    ht.display();

    return 0;
}

// Using std::unordered_map (C++ standard hash table)
#include <iostream>
#include <unordered_map>
