using namespace std;

int main() {
    unordered_map<string, int> scores;

    // Insertion
    scores["Alice"] = 95;
    scores["Bob"] = 87;
    scores["Carol"] = 92;

    // Access
    cout << "Alice's score: " << scores["Alice"] << "\n";

    // Check existence
    if (scores.find("Bob") != scores.end())
        cout << "Bob is in the map\n";

    // Iteration (order is NOT guaranteed!)
    cout << "\nAll entries:\n";
    for (const auto& pair : scores) {
        cout << pair.first << " => " << pair.second << "\n";
    }

    // Count frequencies
    string text = "hello world hello";
    unordered_map<string, int> freq;
    string word;
    for (char c : text) {
        if (c == ' ') {
            if (!word.empty()) { freq[word]++; word.clear(); }
        } else {
            word += c;
        }
    }
    if (!word.empty()) freq[word]++;

    cout << "\nWord frequencies:\n";
    for (const auto& p : freq)
        cout << p.first << ": " << p.second << "\n";

    return 0;
}

// Sorting algorithms from scratch
#include <iostream>
#include <vector>
using namespace std;

void bubbleSort(vector<int>& arr) {
    int n = arr.size();
    for (int i = 0; i < n - 1; i++) {
        bool swapped = false;
        for (int j = 0; j < n - i - 1; j++) {
            if (arr[j] > arr[j + 1]) {
                swap(arr[j], arr[j + 1]);
                swapped = true;
            }
        }
        if (!swapped) break;  // Already sorted
    }
}

void selectionSort(vector<int>& arr) {
    int n = arr.size();
    for (int i = 0; i < n - 1; i++) {
        int minIdx = i;
        for (int j = i + 1; j < n; j++)
            if (arr[j] < arr[minIdx])
                minIdx = j;
        swap(arr[i], arr[minIdx]);
    }
}

void insertionSort(vector<int>& arr) {
    int n = arr.size();
    for (int i = 1; i < n; i++) {
        int key = arr[i];
        int j = i - 1;
        while (j >= 0 && arr[j] > key) {
            arr[j + 1] = arr[j];
            j--;
        }
        arr[j + 1] = key;
    }
}

void merge(vector<int>& arr, int left, int mid, int right) {
    int n1 = mid - left + 1;
    int n2 = right - mid;
    vector<int> L(n1), R(n2);

    for (int i = 0; i < n1; i++) L[i] = arr[left + i];
    for (int i = 0; i < n2; i++) R[i] = arr[mid + 1 + i];

    int i = 0, j = 0, k = left;
    while (i < n1 && j < n2)
        arr[k++] = (L[i] <= R[j]) ? L[i++] : R[j++];
    while (i < n1) arr[k++] = L[i++];
    while (j < n2) arr[k++] = R[j++];
}

void mergeSort(vector<int>& arr, int left, int right) {
    if (left < right) {
        int mid = left + (right - left) / 2;
        mergeSort(arr, left, mid);
        mergeSort(arr, mid + 1, right);
        merge(arr, left, mid, right);
    }
}

void print(const vector<int>& arr) {
    for (int x : arr) cout << x << " ";
    cout << "\n";
}

int main() {
    vector<int> original = {64, 34, 25, 12, 22, 11, 90};

    vector<int> a1 = original;
    bubbleSort(a1);
    cout << "Bubble:    "; print(a1);

    vector<int> a2 = original;
    selectionSort(a2);
    cout << "Selection: "; print(a2);

    vector<int> a3 = original;
    insertionSort(a3);
    cout << "Insertion: "; print(a3);

    vector<int> a4 = original;
    mergeSort(a4, 0, a4.size() - 1);
    cout << "Merge:     "; print(a4);

    return 0;
}

// Stability demonstration and std::sort usage
#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

struct Employee {
    string name;
    int salary;
    string dept;
};

bool compareBySalary(const Employee& a, const Employee& b) {
    return a.salary < b.salary;
}

int main() {
    vector<Employee> staff = {
        {"Alice", 50000, "Engineering"},
        {"Bob", 45000, "Sales"},
        {"Carol", 50000, "Marketing"},
        {"David", 45000, "Engineering"}
    };

    // Stable sort preserves relative order of equal elements
    stable_sort(staff.begin(), staff.end(), compareBySalary);

    cout << "After stable_sort by salary:\n";
    for (const auto& e : staff)
        cout << e.name << " (" << e.dept << ") - $" << e.salary << "\n";

    // std::sort (unstable) - faster but may reorder equal elements
    vector<int> nums = {5, 2, 8, 1, 9, 3};
    sort(nums.begin(), nums.end());
    cout << "\nSorted numbers: ";
    for (int n : nums) cout << n << " ";
    cout << "\n";

    // Binary search requires sorted data
    if (binary_search(nums.begin(), nums.end(), 8))
        cout << "8 is in the array\n";

    return 0;
}
